 const byId=new Map(exercises.filter(q=>q&&typeof q.id==='string').map(q=>[q.id,q]));
 const sessions=history.journal.filter(e=>e&&e.mode==='parcours'&&Number.isInteger(e.session)&&e.session>=1&&e.session<=history.completed&&e.session>history.completed-WINDOW&&Array.isArray(e.answers));
 const counts=new Map();for(const e of sessions)counts.set(e.session,(counts.get(e.session)||0)+1);
 const groups=new Map(),success=[];
